#include <bits/stdc++.h>
using namespace std;
using Prog=vector<array<char,6>>;
const int DR[6]={0,1,1,0,-1,-1},DC[6]={2,1,-1,-2,-1,1};
struct Case{int r,h,w,cnt; vector<string> g; vector<pair<int,int>> cells;};
struct Geo{int r,n,h,w;vector<pair<int,int>> ring;vector<vector<int>> ent;vector<pair<int,int>> cells;vector<vector<int>> id; Geo(int rad):r(rad),n(6*r),h(2*r+1),w(4*r+1){id.assign(h,vector<int>(w,-1));for(int row=1;row<2*r;row++){int d=abs(r-row);for(int col=d+2;col<4*r-d;col+=2){id[row][col]=cells.size();cells.push_back({row,col});}}for(int i=r;i>0;i--)ring.push_back({i,r-i});for(int k=0;k<=r;k++)ring.push_back({0,r+2*k});for(int i=1;i<=r;i++)ring.push_back({i,4*r-(r-i)});for(int i=r+1;i<=2*r;i++)ring.push_back({i,4*r-(i-r)});for(int k=1;k<=r;k++)ring.push_back({2*r,3*r-2*k});for(int i=2*r-1;i>r;i--)ring.push_back({i,i-r});ent.assign(6,vector<int>(cells.size(),-1));for(int e=0;e<6;e++)for(int p=0;p<n;p++){auto[row,col]=ring[p];row+=DR[e];col+=DC[e];while(row>=0&&row<h&&col>=0&&col<w&&id[row][col]>=0){ent[e][id[row][col]]=p;row+=DR[e];col+=DC[e];}}}};
struct PairGraph{int a,b,n,nn,N;vector<int> inter;vector<array<int,16>> adj;vector<uint8_t> deg;vector<int> goals;vector<int> goalid;int start;PairGraph(const Geo&geo,const Case&cs,int aa,int bb):a(aa),b(bb),n(geo.n),nn(n*n),N(4*nn){vector<bool> pat(geo.cells.size()),forbid(geo.cells.size());for(auto[row,col]:cs.cells)pat[geo.id[row][col]]=true;for(auto[row,col]:cs.cells)for(int k=0;k<6;k++){int rr=row+DR[k],cc=col+DC[k];if(rr>=0&&rr<geo.h&&cc>=0&&cc<geo.w&&geo.id[rr][cc]>=0&&!pat[geo.id[rr][cc]])forbid[geo.id[rr][cc]]=true;}
inter.assign(nn,-1);for(int i=0;i<(int)geo.cells.size();i++)inter[geo.ent[a][i]*n+geo.ent[b][i]]=i;
for(auto[row,col]:cs.cells){int c=geo.id[row][col];goals.push_back(3*nn+geo.ent[a][c]*n+geo.ent[b][c]);}goalid.assign(N,-1);for(int i=0;i<(int)goals.size();i++)goalid[goals[i]]=i;
start=(a*geo.r)*n+(b*geo.r);adj.resize(N);deg.assign(N,0);
for(int state=0;state<N;state++){int on=state/nn,q=state%nn,x=q/n,y=q%n; if(on==3&&inter[q]>=0&&forbid[inter[q]])continue;for(int ac=0;ac<4;ac++)for(int bc=0;bc<4;bc++){int nx=(x+(ac==1?1:ac==2?n-1:0))%n,ny=(y+(bc==1?1:bc==2?n-1:0))%n,no=on^(ac==3?1:0)^(bc==3?2:0),np=nx*n+ny;if(no==3&&inter[np]>=0&&forbid[inter[np]])continue;int dest=no*nn+np;if(dest!=state)adj[state][deg[state]++]=dest;}}
}
vector<int> bfs(int source,vector<int>*par=nullptr,int target=-1){vector<int>d(N,-1),q(N);if(par)par->assign(N,-1);d[source]=0;q[0]=source;int lo=0,hi=1,remaining=goals.size();if(goalid[source]>=0)remaining--;while(lo<hi){int s=q[lo++];if(s==target)break;if(target<0&&remaining==0)break;for(int k=0;k<deg[s];k++){int t=adj[s][k];if(d[t]>=0)continue;d[t]=d[s]+1;if(par)(*par)[t]=s;q[hi++]=t;if(goalid[t]>=0)remaining--;}}return d;}
vector<array<char,6>> path(int s,int t){vector<int>par;bfs(s,&par,t);vector<int> p;for(int cur=t;cur!=s;cur=par[cur]){if(cur<0)throw runtime_error("bad BFS path");p.push_back(cur);}reverse(p.begin(),p.end());Prog out;for(int cur:p){array<char,6>o={'-','-','-','-','-','-'};int on=s/nn,non=cur/nn,x=s%nn/n,y=s%n,nx=cur%nn/n,ny=cur%n;o[a]=((on^non)&1)?'T':nx==x?'-':nx==(x+1)%n?'F':'B';o[b]=((on^non)&2)?'T':ny==y?'-':ny==(y+1)%n?'F':'B';out.push_back(o);s=cur;}return out;}
};
mt19937 rng(194839);
int cost(const vector<int>&p,const vector<vector<int>>&d,const vector<int>&st,int cnt){int z=st[p[0]];for(int i=1;i<(int)p.size();i++)z+=cnt*d[p[i-1]][p[i]];return z;}
void improve(vector<int>&p,const vector<vector<int>>&d,const vector<int>&st,int cnt){int n=p.size();for(int it=0;it<10;it++){bool change=false;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){int old=(i?cnt*d[p[i-1]][p[i]]:st[p[i]])+(j+1<n?cnt*d[p[j]][p[j+1]]:0);int ne=(i?cnt*d[p[i-1]][p[j]]:st[p[j]])+(j+1<n?cnt*d[p[i]][p[j+1]]:0);if(ne<old){reverse(p.begin()+i,p.begin()+j+1);change=true;}}if(!change)break;}for(int it=0;it<4;it++){bool change=false;for(int i=0;i<n;i++)for(int j=0;j<n;j++){if(i==j||i+1==j)continue;int u=p[i],old=(i?cnt*d[p[i-1]][u]:st[u])+(i+1<n?cnt*d[u][p[i+1]]:0);int ne=(i+1<n?(i?cnt*d[p[i-1]][p[i+1]]:st[p[i+1]]):0);if(j<i){old+=(j?cnt*d[p[j-1]][p[j]]:st[p[j]]);ne+=(j?cnt*d[p[j-1]][u]:st[u])+cnt*d[u][p[j]];}else {old+=cnt*d[p[j-1]][p[j]];ne+=cnt*d[p[j-1]][u]+cnt*d[u][p[j]];}if(ne<old){p.erase(p.begin()+i);p.insert(p.begin()+(j>i?j-1:j),u);change=true;break;}}if(!change)break;}}
vector<int> route(const vector<vector<int>>&d,const vector<int>&st,int cnt,int effort){int n=d.size();if(n==1)return {0};if(n<=14){int masks=1<<n;vector<int>dp((size_t)masks*n,1e9);vector<int8_t>prev((size_t)masks*n,-1);for(int i=0;i<n;i++)dp[(1<<i)*n+i]=st[i];for(int m=1;m<masks;m++)for(int i=0;i<n;i++)if(m>>i&1){int v=dp[m*n+i];for(int j=0;j<n;j++)if(!(m>>j&1)){int at=(m|1<<j)*n+j,x=v+cnt*d[i][j];if(x<dp[at]){dp[at]=x;prev[at]=i;}}}int last=0;for(int i=1;i<n;i++)if(dp[(masks-1)*n+i]<dp[(masks-1)*n+last])last=i;vector<int>p;for(int m=masks-1;m;){p.push_back(last);int j=prev[m*n+last];m^=1<<last;last=j;}reverse(p.begin(),p.end());return p;}
vector<int> best;int val=1e9;vector<int> starts(n);iota(starts.begin(),starts.end(),0);stable_sort(starts.begin(),starts.end(),[&](int a,int b){return st[a]<st[b];});int trials=min(n,max(12,effort));for(int trial=0;trial<trials;trial++){int first=starts[trial];vector<int>p={first};vector<bool>used(n);used[first]=true;for(int k=1;k<n;k++){int nxt=-1,v=1e9;for(int j=0;j<n;j++)if(!used[j]){int x=d[p.back()][j]*1000+int(rng()%350);if(x<v){v=x;nxt=j;}}p.push_back(nxt);used[nxt]=true;}improve(p,d,st,cnt);int c=cost(p,d,st,cnt);if(c<val){val=c;best=p;}}
vector<int>p=best;int cur=val;int iterations=effort*10000;for(int it=0;it<iterations;it++){int i=rng()%n,j=rng()%n;if(i>j)swap(i,j);if(i==j)continue;int old=(i?cnt*d[p[i-1]][p[i]]:st[p[i]])+(j+1<n?cnt*d[p[j]][p[j+1]]:0),ne=(i?cnt*d[p[i-1]][p[j]]:st[p[j]])+(j+1<n?cnt*d[p[i]][p[j+1]]:0),delta=ne-old;double temp=cnt*(0.05+1.2*pow(1.0-double(it%20000)/20000,3));if(delta<=0||double(rng())/rng.max()<exp(-delta/temp)){reverse(p.begin()+i,p.begin()+j+1);cur+=delta;if(cur<val){val=cur;best=p;}}if(it%20000==19999){p=best;cur=val;}}improve(best,d,st,cnt);return best;}
Prog solve(const Case&cs,int effort){Geo geo(cs.r);Prog best;for(int a=0;a<3;a++)for(int b=a+1;b<3;b++){PairGraph graph(geo,cs,a,b);int p=cs.cells.size();vector<vector<int>> d(p,vector<int>(p));for(int i=0;i<p;i++){auto dst=graph.bfs(graph.goals[i]);for(int j=0;j<p;j++)d[i][j]=dst[graph.goals[j]];}auto dst=graph.bfs(graph.start);vector<int> st;for(int g:graph.goals)st.push_back(dst[g]);auto ord=route(d,st,cs.cnt,effort);
vector<Prog> edges;for(int i=1;i<p;i++)edges.push_back(graph.path(graph.goals[ord[i-1]],graph.goals[ord[i]]));Prog program;vector<bool>painted(p);int got=0,count=0,state=graph.start;
auto emit=[&](array<char,6>line){if(count>=cs.cnt)return;int on=state/graph.nn,x=state%graph.nn/graph.n,y=state%graph.n;char oa=line[a],ob=line[b];if(oa=='T')on^=1;else if(oa=='F')x=(x+1)%graph.n;else if(oa=='B')x=(x+graph.n-1)%graph.n;if(ob=='T')on^=2;else if(ob=='F')y=(y+1)%graph.n;else if(ob=='B')y=(y+graph.n-1)%graph.n;state=on*graph.nn+x*graph.n+y;program.push_back(line);int id=graph.goalid[state];if(id>=0&&!painted[id]){painted[id]=true;got++;if(got==p){count++;got=0;fill(painted.begin(),painted.end(),false);}}};
for(auto line:graph.path(graph.start,graph.goals[ord[0]]))emit(line);bool fw=true;while(count<cs.cnt){if(fw){for(auto&edge:edges)for(auto line:edge)emit(line);}else{for(auto it=edges.rbegin();it!=edges.rend();it++)for(auto jt=it->rbegin();jt!=it->rend();jt++){auto line=*jt;for(auto &c:line){if(c=='F')c='B';else if(c=='B')c='F';}emit(line);}}if(count<cs.cnt)emit({'-','-','-','-','-','-'});fw=!fw;}
if(best.empty()||program.size()<best.size())best=move(program);}return best;}
int main(int argc,char**argv){if(argc<3){cerr<<"input output [effort]\n";return 1;}ifstream in(argv[1]);ofstream out(argv[2]);int n;in>>n;long long total=0;int effort=argc>3?stoi(argv[3]):16;auto start=chrono::steady_clock::now();for(int i=0;i<n;i++){Case cs;in>>cs.r>>cs.h>>cs.w>>cs.cnt;cs.g.resize(cs.h);for(int row=0;row<cs.h;row++){in>>cs.g[row];for(int col=0;col<cs.w;col++)if(cs.g[row][col]=='M')cs.cells.push_back({row,col});}auto prog=solve(cs,effort);if(i)out<<'\n';for(auto line:prog){for(int k=0;k<6;k++){if(k)out<<' ';out<<line[k];}out<<'\n';}out.flush();total+=prog.size();cerr<<i+1<<'/'<<n<<" score "<<prog.size()<<" total "<<total<<" elapsed "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}cerr<<"TOTAL "<<total<<'\n';}
